import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"VeilChat: Un Mensajero Sin Servidores Que Vulnerar","description":"La historia de construir VeilChat — un mensajero P2P serverless con cifrado de extremo a extremo, conexiones TCP directas y cero metadatos.","frontmatter":{"title":"VeilChat: Un Mensajero Sin Servidores Que Vulnerar","description":"La historia de construir VeilChat — un mensajero P2P serverless con cifrado de extremo a extremo, conexiones TCP directas y cero metadatos."},"headers":[],"relativePath":"es/vibe-stories/story-2/index.md","filePath":"es/vibe-stories/story-2/index.md"}`),a={name:`es/vibe-stories/story-2/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="veilchat-un-mensajero-sin-servidores-que-vulnerar" tabindex="-1">VeilChat: Un Mensajero Sin Servidores Que Vulnerar <a class="header-anchor" href="#veilchat-un-mensajero-sin-servidores-que-vulnerar" aria-label="Permalink to “VeilChat: Un Mensajero Sin Servidores Que Vulnerar”">​</a></h1><p>Todos los mensajeros convencionales dependen en silencio de una infraestructura que sabe <em>quién</em> habla con <em>quién</em>, incluso cuando no puede leer el contenido. Los metadatos son el modelo de negocio. Quise saber hasta dónde podía empujar en la dirección contraria — así nació <strong><a href="https://github.com/Godde3s/veilchat" target="_blank" rel="noreferrer">VeilChat</a></strong>: dos pares, una conexión TCP directa y un canal cifrado que nunca toca a un tercero.</p><h2 id="la-restriccion-de-diseno" tabindex="-1">La restricción de diseño <a class="header-anchor" href="#la-restriccion-de-diseno" aria-label="Permalink to “La restricción de diseño”">​</a></h2><p>Sin cuentas. Sin servidores. Sin números de teléfono. Sin metadatos. Esa restricción lo decidió todo. No hay flujo de registro porque no hay nada en qué registrarse; no hay relay de mensajes porque no existe una empresa de relays. Dos pares se descubren — por LAN o marcado directo — ejecutan un intercambio de claves con autenticación mutua, y desde ese momento cada byte en el cable es una trama AEAD cifrada.</p><h2 id="las-partes-dificiles" tabindex="-1">Las partes difíciles <a class="header-anchor" href="#las-partes-dificiles" aria-label="Permalink to “Las partes difíciles”">​</a></h2><ul><li><strong>Intercambio de claves bien hecho</strong> — handshake X25519 con autenticación mutua, claves de sesión derivadas con HKDF y verificación de transcript, para que ni un escuchador pasivo ni un impostor activo aprendan nada.</li><li><strong>El protocolo de cable</strong> — una cabecera de nonce de 24 bytes más tramas ChaCha20-Poly1305: protección contra replay e integridad sin un solo byte de metadatos en claro.</li><li><strong>Entrega NAT-friendly</strong> — descubrimiento por LAN para el caso común, marcado directo para todo lo demás, con el handshake reintentado hasta que ambos lados confirman.</li></ul><h2 id="lo-que-demuestra" tabindex="-1">Lo que demuestra <a class="header-anchor" href="#lo-que-demuestra" aria-label="Permalink to “Lo que demuestra”">​</a></h2><p>VeilChat son aproximadamente 1.000 líneas de Python legible y auditable — CLI y librería importable. Construí desde cero las partes difíciles de un mensajero: gestión de claves, diseño del handshake, protocolo de cable, entrega cifrada. Es la diferencia entre <em>usar</em> librerías de criptografía y <em>diseñar con</em> ellas, y es el proyecto al que recurro cuando alguien pregunta si entiendo la seguridad como ingeniería y no como una lista de verificación.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};